(1152, 1, '2026-04-27 20:27:13', '2026-04-27 23:27:13', '<!-- wp:query {\"queryId\":4,\"query\":{\"perPage\":3,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"author\":\"\",\"search\":\"\",\"exclude\":[],\"sticky\":\"\",\"inherit\":false},\"metadata\":{\"categories\":[\"posts\"],\"patternName\":\"core/query-standard-posts\",\"name\":\"Padrão\"}} -->\n<div class=\"wp-block-query\"><!-- wp:post-template -->\n<!-- wp:post-title {\"isLink\":true} /-->\n\n<!-- wp:post-featured-image {\"isLink\":true,\"align\":\"wide\"} /-->\n\n<!-- wp:post-excerpt /-->\n\n<!-- wp:separator {\"opacity\":\"css\"} -->\n<hr class=\"wp-block-separator has-css-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:post-date {\"metadata\":{\"bindings\":{\"datetime\":{\"source\":\"core/post-data\",\"args\":{\"field\":\"date\"}}}}} /-->\n<!-- /wp:post-template --></div>\n<!-- /wp:query -->', 'Post', '', 'inherit', 'closed', 'closed', '', '960-revision-v1', '', '', '2026-04-27 20:27:13', '2026-04-27 23:27:13', '', 960, 'http://localhost/wordpress/?p=1152', 0, 'revision', '', 0),
